--- /dev/null
+++ b/firmware/src/hacks/ad_flyingtoasters/ad_flyingtoasters.c
@@ -0,0 +1,168 @@
+/* ad-flyingtoasters: a recreation of Flying Toasters from Berkeley Systems'
+ * After Dark 2.0, (c) 1990-91 Berkeley Systems, by Jack Eastman, Bruce
+ * Burkhalter, Patrick Beard and Tomoya Ikeda. This code is ours (MIT); the
+ * art is read at build time from the user's own copy of the After Dark disk
+ * (https://archive.org/details/after-dark-2.0v-800k) and never committed. */
+
+#ifdef HAVE_AFTER_DARK_TOASTERS
+
+#include <stdint.h>
+#include <stdio.h>
+#include <stdlib.h>
+#include <string.h>
+
+#include "after_dark/toaster_sprites.h"
+#include "core/canvas.h"
+#include "doubletime.h"
+#include "hacks/ad_flyingtoasters/ad_sim.h"
+#include "hacks/ad_flyingtoasters/ad_sprites.h"
+#include "runner/hack_entry.h"
+
+#ifdef ESP_PLATFORM
+#include <esp_random.h>
+#endif
+
+#if defined(AD_TOASTERS_ART) && AD_TOASTERS_ART != 0 && AD_TOASTERS_ART != 1
+#error "AD_TOASTERS_ART must be 0 (1-bit) or 1 (colour)"
+#endif
+#if defined(AD_TOASTERS_DONENESS) && AD_TOASTERS_DONENESS != 0 && \
+    AD_TOASTERS_DONENESS != 1 && AD_TOASTERS_DONENESS != 2
+#error "AD_TOASTERS_DONENESS must be 0 (light), 1 (medium) or 2 (dark)"
+#endif
+
+#define AD_SPRITES 5
+#ifndef AD_TOASTERS_SCALE
+#define AD_TOASTERS_SCALE 2
+#endif
+#if AD_TOASTERS_SCALE != 1 && AD_TOASTERS_SCALE != 2
+#error "AD_TOASTERS_SCALE must be 1 (original size) or 2 (chunky pixels)"
+#endif
+#define AD_S AD_TOASTERS_SCALE
+#define AD_SIDE (AD_RECT * AD_S)
+#define AD_COUNT (AD_S == 1 ? 10 : 6)
+
+typedef struct {
+  Display *dpy;
+  Window window;
+  GC gc;
+  XImage *sprite[AD_SPRITES];
+  AdSim sim;
+} State;
+
+static const char *const ad_flyingtoasters_defaults[] = {".background: black", 0};
+
+/* random() on the device replays the same sequence after every boot, so the
+ * picks take real entropy there; host builds (tests, dump) keep random() so
+ * their frames repeat. */
+static uint32_t ad_entropy(void) {
+#ifdef ESP_PLATFORM
+  return esp_random();
+#else
+  return (uint32_t)random();
+#endif
+}
+
+static void ad_flyingtoasters_free(Display *dpy, Window window, void *closure);
+
+static XImage *make_sprite(Display *dpy, const unsigned char *rgb) {
+  XImage *im = XCreateImage(dpy, NULL, 16, ZPixmap, 0, NULL, AD_SIDE, AD_SIDE, 16, 0);
+  if (!im) return NULL;
+  uint16_t *px = malloc(AD_SIDE * AD_SIDE * sizeof *px);
+  uint16_t *one = malloc(AD_RECT * AD_RECT * sizeof *one);
+  if (!px || !one) {
+    free(one);
+    free(px);
+    XDestroyImage(im);
+    return NULL;
+  }
+  ad_build_sprite(rgb, one);
+  /* XPutImage copies image pixels as they are, and the canvas keeps RGB565
+   * with its bytes swapped (xshim.h's comment saying it swaps is stale). */
+  ad_scale_sprite(one, AD_RECT, AD_S, px);
+  free(one);
+  for (int i = 0; i < AD_SIDE * AD_SIDE; i++) px[i] = px_swap(px[i]);
+  im->data = (char *)px;
+  return im;
+}
+
+static void blit(void *ctx, const AdRect *r, int sprite) {
+  State *st = ctx;
+  XPutImage(st->dpy, st->window, st->gc, st->sprite[sprite], 0, 0, r->left * AD_S,
+            r->top * AD_S, AD_SIDE, AD_SIDE);
+}
+
+static void *ad_flyingtoasters_init(Display *dpy, Window window) {
+  State *st = calloc(1, sizeof *st);
+  if (!st) return NULL;
+  st->dpy = dpy;
+  st->window = window;
+  st->gc = XCreateGC(dpy, window, 0, NULL);
+
+  AdChoice pick = ad_choose(ad_entropy());
+#ifdef AD_TOASTERS_ART
+  pick.colour = AD_TOASTERS_ART;
+#endif
+#ifdef AD_TOASTERS_DONENESS
+  pick.doneness = (AdDoneness)AD_TOASTERS_DONENESS;
+#endif
+
+  unsigned char *rgb = malloc(64 * 64 * 3);
+  if (!rgb) {
+    ad_flyingtoasters_free(dpy, window, st);
+    return NULL;
+  }
+  for (int s = 0; s < AD_SPRITES; s++) {
+    if (pick.colour) {
+      memcpy(rgb, ad_colour_rgb[s], 64 * 64 * 3);
+      if (s == 4) ad_apply_doneness(rgb, 64 * 64, pick.doneness);
+    } else {
+      ad_expand_mono(ad_mono_bits[s], rgb);
+    }
+    st->sprite[s] = make_sprite(dpy, rgb);
+    if (!st->sprite[s]) {
+      free(rgb);
+      ad_flyingtoasters_free(dpy, window, st);
+      return NULL;
+    }
+  }
+  free(rgb);
+
+  static const char *const doneness[] = {"light", "medium", "dark"};
+  fprintf(stderr, "ad-flyingtoasters: %s, doneness=%s\n",
+          pick.colour ? "colour" : "1-bit", doneness[pick.doneness]);
+
+  XWindowAttributes xgwa;
+  XGetWindowAttributes(dpy, window, &xgwa);
+  AdRect bounds = {0, 0, xgwa.height / AD_S, xgwa.width / AD_S};
+  ad_sim_init(&st->sim, bounds, AD_COUNT, random);
+  ad_sim_draw_all(&st->sim, blit, st);
+  return st;
+}
+
+static unsigned long ad_flyingtoasters_draw(Display *dpy, Window window, void *closure) {
+  (void)dpy;
+  (void)window;
+  State *st = closure;
+  const double started = double_time();
+  if (st) ad_sim_step(&st->sim, blit, st);
+  /* The runner waits this long after the push and counts only the push
+   * against it, so subtract the step to hold 30 steps a second. */
+  const long left = 33333 - (long)((double_time() - started) * 1e6);
+  return left > 0 ? (unsigned long)left : 0;
+}
+
+static void ad_flyingtoasters_free(Display *dpy, Window window, void *closure) {
+  (void)window;
+  State *st = closure;
+  if (!st) return;
+  for (int s = 0; s < AD_SPRITES; s++)
+    if (st->sprite[s]) XDestroyImage(st->sprite[s]);
+  if (st->gc) XFreeGC(dpy, st->gc);
+  free(st);
+}
+
+const HackEntry ad_flyingtoasters_hack = {
+    "ad-flyingtoasters", ad_flyingtoasters_defaults, ad_flyingtoasters_init,
+    ad_flyingtoasters_draw, ad_flyingtoasters_free};
+
+#endif
diff --git a/firmware/src/hacks/ad_flyingtoasters/ad_sim.c b/firmware/src/hacks/ad_flyingtoasters/ad_sim.c
new file mode 100644
index 0000000..8848d33
--- /dev/null
+++ b/firmware/src/hacks/ad_flyingtoasters/ad_sim.c
@@ -0,0 +1,149 @@
+#include "ad_sim.h"
+
+#include <stdlib.h>
+
+#define TRIES 4
+
+static AdRect offset(AdRect r, int dh, int dv) {
+  r.left += dh;
+  r.right += dh;
+  r.top += dv;
+  r.bottom += dv;
+  return r;
+}
+
+static int intersects(const AdRect *a, const AdRect *b) {
+  return a->left < b->right && b->left < a->right && a->top < b->bottom && b->top < a->bottom;
+}
+
+static long rnd_mod(const AdSim *sim, long k) { return labs(sim->rnd() % k); }
+
+static AdRect random_inside_rect(const AdSim *sim) {
+  int w = sim->bounds.right - sim->bounds.left;
+  int h = sim->bounds.bottom - sim->bounds.top;
+  AdRect r;
+  r.top = sim->bounds.top + (int)rnd_mod(sim, h - AD_RECT);
+  r.left = sim->bounds.left + (int)rnd_mod(sim, w - AD_RECT);
+  r.bottom = r.top + AD_RECT;
+  r.right = r.left + AD_RECT;
+  return r;
+}
+
+static AdRect random_edge_rect(const AdSim *sim) {
+  int w = sim->bounds.right - sim->bounds.left;
+  int h = sim->bounds.bottom - sim->bounds.top;
+  AdRect r;
+  if (sim->rnd() % 2 != 0) {
+    r.bottom = sim->bounds.top;
+    r.left = sim->bounds.left + (int)rnd_mod(sim, w);
+    r.top = r.bottom - AD_RECT;
+    r.right = r.left + AD_RECT;
+  } else {
+    r.left = sim->bounds.right;
+    r.top = sim->bounds.top + (int)rnd_mod(sim, h);
+    r.right = r.left + AD_RECT;
+    r.bottom = r.top + AD_RECT;
+  }
+  return r;
+}
+
+int ad_sim_collision(const AdSim *sim, int i, AdRect cand, int *dv, int *dh) {
+  for (int k = 0; k < sim->n; k++) {
+    const AdFlyer *o = &sim->f[k];
+    if (k == i || !o->live || !intersects(&o->r, &cand)) continue;
+    int dl = o->r.left - cand.left;
+    int dt = o->r.top - cand.top;
+    if (abs(dt) < abs(dl)) {
+      *dv = -1;
+      *dh = 0;
+    } else {
+      *dv = 0;
+      *dh = cand.top < o->r.top ? -1 : 1;
+    }
+    return 1;
+  }
+  return 0;
+}
+
+static void create_flyer(AdSim *sim, int i) {
+  AdRect r = {0, 0, 0, 0};
+  int placed = 0;
+  for (int t = 0; t < TRIES && !placed; t++) {
+    r = sim->running ? random_edge_rect(sim) : random_inside_rect(sim);
+    int dv, dh;
+    placed = !ad_sim_collision(sim, i, r, &dv, &dh);
+  }
+  if (!placed) return;
+  long roll = rnd_mod(sim, 100);
+  AdFlyer *f = &sim->f[i];
+  f->live = 1;
+  f->toast = roll >= 75;
+  f->speed = f->toast ? 1 : roll >= 50 ? 3 : roll >= 25 ? 2 : 1;
+  f->frame = 0;
+  f->flap_down = 0;
+  f->r = r;
+}
+
+void ad_sim_init(AdSim *sim, AdRect bounds, int n, long (*rnd)(void)) {
+  if (n > AD_MAX_FLYERS) n = AD_MAX_FLYERS;
+  if (n < 0) n = 0;
+  for (int i = 0; i < AD_MAX_FLYERS; i++) sim->f[i] = (AdFlyer){0};
+  sim->bounds = bounds;
+  sim->n = n;
+  sim->rnd = rnd;
+  sim->running = 0;
+  for (int i = 0; i < n; i++) create_flyer(sim, i);
+  sim->running = 1;
+}
+
+static void draw_flyer(AdFlyer *f, AdDrawFn draw, void *ctx) {
+  draw(ctx, &f->r, f->toast ? 4 : f->frame);
+  if (f->toast) return;
+  if (f->flap_down) {
+    if (f->frame == 0) {
+      f->frame = 1;
+      f->flap_down = 0;
+    } else {
+      f->frame--;
+    }
+  } else if (f->frame == 3) {
+    f->frame = 2;
+    f->flap_down = 1;
+  } else {
+    f->frame++;
+  }
+}
+
+void ad_sim_draw_all(AdSim *sim, AdDrawFn draw, void *ctx) {
+  for (int i = 0; i < sim->n; i++) {
+    if (sim->f[i].live) draw_flyer(&sim->f[i], draw, ctx);
+  }
+}
+
+void ad_sim_step(AdSim *sim, AdDrawFn draw, void *ctx) {
+  for (int i = 0; i < sim->n; i++) {
+    if (!sim->f[i].live) create_flyer(sim, i);
+    if (sim->f[i].live) sim->f[i].r = offset(sim->f[i].r, -2, 1);
+  }
+  for (int i = 0; i < sim->n; i++) {
+    AdFlyer *f = &sim->f[i];
+    if (!f->live) continue;
+    if (!intersects(&f->r, &sim->bounds)) {
+      f->live = 0;
+      continue;
+    }
+    int s = f->speed - 1;
+    if (s > 0) {
+      AdRect cand = offset(f->r, -2 * s, s);
+      int dv, dh;
+      if (ad_sim_collision(sim, i, cand, &dv, &dh)) {
+        cand = offset(f->r, dh, -2 * dv);
+        int dv2, dh2;
+        if (!ad_sim_collision(sim, i, cand, &dv2, &dh2)) f->r = cand;
+      } else {
+        f->r = cand;
+      }
+    }
+    draw_flyer(f, draw, ctx);
+  }
+}
diff --git a/firmware/src/hacks/ad_flyingtoasters/ad_sim.h b/firmware/src/hacks/ad_flyingtoasters/ad_sim.h
new file mode 100644
index 0000000..67a8494
--- /dev/null
+++ b/firmware/src/hacks/ad_flyingtoasters/ad_sim.h
@@ -0,0 +1,37 @@
+#ifndef AD_SIM_H
+#define AD_SIM_H
+
+#define AD_MAX_FLYERS 20
+#define AD_RECT 70 /* flyer rect: 64 art + 6 px strip */
+#define AD_STRIP 6
+
+/* QuickDraw order; right and bottom are exclusive. */
+typedef struct {
+  int top, left, bottom, right;
+} AdRect;
+
+typedef struct {
+  int live, toast, speed, frame, flap_down;
+  AdRect r;
+} AdFlyer;
+
+typedef struct {
+  AdRect bounds;
+  int n, running;
+  AdFlyer f[AD_MAX_FLYERS];
+  long (*rnd)(void); /* random() in the hack; scripted in tests */
+} AdSim;
+
+/* sprite: 0-3 toaster frame, 4 toast. Called after the flyer's move. */
+typedef void (*AdDrawFn)(void *ctx, const AdRect *r, int sprite);
+
+/* Scatter n flyers inside bounds. Does not draw. */
+void ad_sim_init(AdSim *, AdRect bounds, int n, long (*rnd)(void));
+/* Draw each live flyer once, in slot order (advances toaster frames). */
+void ad_sim_draw_all(AdSim *, AdDrawFn, void *ctx);
+/* One simulation step: move, respawn, collide, draw. */
+void ad_sim_step(AdSim *, AdDrawFn, void *ctx);
+/* First live flyer (other than slot i) overlapping cand: sets the nudge. */
+int ad_sim_collision(const AdSim *, int i, AdRect cand, int *dv, int *dh);
+
+#endif
diff --git a/firmware/src/hacks/ad_flyingtoasters/ad_sprites.c b/firmware/src/hacks/ad_flyingtoasters/ad_sprites.c
new file mode 100644
index 0000000..dc62bf9
--- /dev/null
+++ b/firmware/src/hacks/ad_flyingtoasters/ad_sprites.c
@@ -0,0 +1,46 @@
+#include "ad_sprites.h"
+
+AdChoice ad_choose(uint32_t r) {
+  AdChoice c;
+  c.colour = (int)(r & 1);
+  c.doneness = (AdDoneness)((r >> 1) % 3);
+  return c;
+}
+
+void ad_apply_doneness(unsigned char *rgb, int pixels, AdDoneness d) {
+  static const int k[3][3] = {{0, 0, 0}, {79, 79, 79}, {127, 111, 111}};
+  if (d == AD_DONE_LIGHT) return;
+  for (int i = 0; i < pixels; i++) {
+    for (int c = 0; c < 3; c++) {
+      int v = rgb[i * 3 + c] - k[d][c];
+      rgb[i * 3 + c] = (unsigned char)(v > 0 ? v : 0);
+    }
+  }
+}
+
+void ad_expand_mono(const unsigned char bits[512], unsigned char rgb[64 * 64 * 3]) {
+  for (int y = 0; y < 64; y++) {
+    for (int x = 0; x < 64; x++) {
+      int set = (bits[y * 8 + (x >> 3)] >> (7 - (x & 7))) & 1;
+      unsigned char v = set ? 0 : 255;
+      unsigned char *p = &rgb[(y * 64 + x) * 3];
+      p[0] = p[1] = p[2] = v;
+    }
+  }
+}
+
+void ad_build_sprite(const unsigned char rgb[64 * 64 * 3], uint16_t out[70 * 70]) {
+  for (int i = 0; i < 70 * 70; i++) out[i] = 0;
+  for (int y = 0; y < 64; y++) {
+    for (int x = 0; x < 64; x++) {
+      const unsigned char *p = &rgb[(y * 64 + x) * 3];
+      out[(y + 6) * 70 + x] = (uint16_t)(((p[0] >> 3) << 11) | ((p[1] >> 2) << 5) | (p[2] >> 3));
+    }
+  }
+}
+
+void ad_scale_sprite(const uint16_t *in, int side, int scale, uint16_t *out) {
+  int big = side * scale;
+  for (int y = 0; y < big; y++)
+    for (int x = 0; x < big; x++) out[y * big + x] = in[(y / scale) * side + x / scale];
+}
