+  const int want[] = {0, 1, 2, 3, 2, 1, 0};
+  TEST_ASSERT_EQUAL_INT(7, rec.count);
+  TEST_ASSERT_EQUAL_INT_ARRAY(want, rec.sprites, 7);
+}
