+  for (int y = 0; y < 70; y++) {
+    for (int x = 0; x < 70; x++) {
+      uint16_t want = (y < 6 || x >= 64) ? 0 : 0xFFFF;
+      TEST_ASSERT_EQUAL_HEX16(want, out[y * 70 + x]);
+    }
+  }
+}
