+  rgb[(3 * 64 + 2) * 3 + 0] = 0xF8;
+  rgb[(3 * 64 + 2) * 3 + 1] = 0x84;
+  rgb[(3 * 64 + 2) * 3 + 2] = 0x08;
+  ad_build_sprite(rgb, out);
+  TEST_ASSERT_EQUAL_HEX16((0x1F << 11) | (0x21 << 5) | 0x01, out[(3 + 6) * 70 + 2]);
+}
