  const size_t early = held_after_starting(hack, 3);
  const size_t late = held_after_starting(hack, 53);
  TEST_ASSERT_TRUE_MESSAGE(late < early + LEAK_SLACK_BYTES,
                           "bytes held at rest grew over 50 more starts");
}
